#include <bits/stdc++.h>
using namespace std;

class MinStack {
private:
    // Storing pairs: {element, minimum from bottom up to this element}
    stack<pair<int, int>> st;

public:
    MinStack() {}

    // 1. Adding an element (Push):
    void push(int new_elem) {
        int new_min = st.empty() ? new_elem : min(new_elem, st.top().second);
        st.push({new_elem, new_min});
    }

    // 2. Removing an element (Pop):
    void pop() {
        if (!st.empty()) {
            st.pop();
        }
    }

    // 3. Inspecting the top element:
    int top() {
        return st.top().first;
    }

    // 4. Finding the minimum in O(1):
    int getMin() {
        return st.top().second;
    }

    // 5. Checking if the stack is empty:
    bool empty() {
        return st.empty();
    }
};

#include <bits/stdc++.h>
using namespace std;

class MinQueueDeque {
private:
    // Storing pairs: {element_value, added_index}
    deque<pair<int, int>> q;
    int cnt_added;
    int cnt_removed;

public:
    MinQueueDeque() : cnt_added(0), cnt_removed(0) {}

    // 1. Finding the minimum in O(1):
    int getMin() {
        return q.front().first;
    }

    // 2. Adding an element (Push / Enqueue):
    void push(int new_elem) {
        while (!q.empty() && q.back().first >= new_elem) {
            q.pop_back();
        }
        q.push_back({new_elem, cnt_added});
        cnt_added++;
    }

    // 3. Removing an element (Pop / Dequeue):
    void pop() {
        if (!q.empty() && q.front().second == cnt_removed) {
            q.pop_front();
        }
        cnt_removed++;
    }

    // 4. Checking if the queue is empty:
    bool empty() {
        return cnt_added == cnt_removed;
    }

    // 5. Total active element count:
    int size() {
        return cnt_added - cnt_removed;
    }
};

#include <bits/stdc++.h>
using namespace std;

class MinQueueTwoStacks {
private:
    // s1 for enqueuing (tail), s2 for dequeuing (head)
    stack<pair<int, int>> s1, s2;

public:
    MinQueueTwoStacks() {}

    // 1. Finding the minimum in O(1):
    int getMin() {
        if (s1.empty() || s2.empty()) {
            return s1.empty() ? s2.top().second : s1.top().second;
        }
        return min(s1.top().second, s2.top().second);
    }

    // 2. Adding an element (Push / Enqueue):
    void push(int new_elem) {
        int cur_min = s1.empty() ? new_elem : min(new_elem, s1.top().second);
        s1.push({new_elem, cur_min});
    }

    // 3. Removing an element (Pop / Dequeue):
    int pop() {
        if (s2.empty()) {
            while (!s1.empty()) {
                int elem = s1.top().first;
                s1.pop();
                int cur_min = s2.empty() ? elem : min(elem, s2.top().second);
                s2.push({elem, cur_min});
            }
        }
        int removed = s2.top().first;
        s2.pop();
        return removed;
    }

    // 4. Checking if the queue is empty:
    bool empty() {
        return s1.empty() && s2.empty();
    }

    // 5. Total active element count:
    int size() {
        return s1.size() + s2.size();
    }
};

#include <bits/stdc++.h>
using namespace std;

class SlidingWindowMin {
public:
    SlidingWindowMin() {}

    // Computes window minimum for each subarray of size k in O(N)
    vector<int> solve(const vector<int>& arr, int k) {
        int n = arr.size();
        vector<int> result;
        if (n == 0 || k <= 0 || k > n) return result;

        // Monotonic deque storing indices of candidate elements
        deque<int> dq;

        for (int i = 0; i < n; i++) {
            // 1. Remove elements outside current window [i - k + 1, i]:
            if (!dq.empty() && dq.front() <= i - k) {
                dq.pop_front();
            }

            // 2. Remove elements from back greater than or equal to arr[i]:
            while (!dq.empty() && arr[dq.back()] >= arr[i]) {
                dq.pop_back();
            }

            // 3. Add current element's index:
            dq.push_back(i);

            // 4. Record minimum once the first window of size k is formed:
            if (i >= k - 1) {
                result.push_back(arr[dq.front()]);
            }
        }

        return result;
    }
};

