using namespace std;

class FenwickTree {
private:
    int n;
    vector<int> bit;

public:
    // 1. 1-based indexing initialization:
    FenwickTree(int n) : n(n), bit(n + 1, 0) {}

    // 2. Point update: Add delta to element at 1-based index idx in O(log N):
    void add(int idx, int delta) {
        for (; idx <= n; idx += idx & (-idx)) {
            bit[idx] += delta;
        }
    }

    // 3. Prefix sum query: sum of elements from 1 to idx in O(log N):
    int query(int idx) {
        int sum = 0;
        for (; idx > 0; idx -= idx & (-idx)) {
            sum += bit[idx];
        }
        return sum;
    }

    // 4. Range sum query: sum of elements in [l, r] in O(log N):
    int range_query(int l, int r) {
        if (l > r) return 0;
        return query(r) - query(l - 1);
    }
};

