class SparseTable {
private:
    int n, K;
    vector<vector<int>> st;
    vector<int> lg;

public:
    // 1. Table Precomputation in O(N log N):
    SparseTable(const vector<int>& a) {
        n = a.size();
        K = 25; // Supports arrays up to 2^25 (~3.3 x 10^7 elements)
        st.assign(K + 1, vector<int>(n));

        // Precompute logarithm lookup table:
        lg.assign(n + 1, 0);
        for (int i = 2; i <= n; i++) {
            lg[i] = lg[i / 2] + 1;
        }

        // Base level 2^0 = 1:
        for (int i = 0; i < n; i++) {
            st[0][i] = a[i];
        }

        // Build dynamic programming transitions:
        for (int i = 1; i <= K; i++) {
            for (int j = 0; j + (1 << i) <= n; j++) {
                st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
            }
        }
    }

    // 2. Range Minimum Query in O(1):
    int query(int l, int r) {
        int i = lg[r - l + 1];
        return min(st[i][l], st[i][r - (1 << i) + 1]);
    }
};

