class Dijkstra {
private:
    int n;
    const long long INF = 1e18;
    vector<vector<pair<int, int>>> adj; // {neighbor, weight}

public:
    Dijkstra(int n) : n(n), adj(n) {}

    // Add directed or undirected edge:
    void addEdge(int u, int v, int w, bool directed = true) {
        adj[u].push_back({v, w});
        if (!directed) {
            adj[v].push_back({u, w});
        }
    }

    // 1. Single-Source Shortest Path in O((V + E) log V):
    pair<vector<long long>, vector<int>> solve(int src) {
        vector<long long> dist(n, INF);
        vector<int> parent(n, -1);
        // Min-heap priority queue storing {distance, vertex}
        priority_queue<pair<long long, int>, 
                       vector<pair<long long, int>>, 
                       greater<pair<long long, int>>> pq;

        dist[src] = 0;
        pq.push({0, src});

        while (!pq.empty()) {
            auto [d_v, v] = pq.top();
            pq.pop();

            // 2. Discard stale priority queue entries:
            if (d_v != dist[v]) {
                continue;
            }

            // 3. Relax all outgoing edges:
            for (auto& edge : adj[v]) {
                int to = edge.first;
                int len = edge.second;

                if (dist[v] + len < dist[to]) {
                    dist[to] = dist[v] + len;
                    parent[to] = v;
                    pq.push({dist[to], to});
                }
            }
        }

        return {dist, parent};
    }

    // 4. Shortest path reconstruction:
    vector<int> getPath(int target, const vector<int>& parent) {
        vector<int> path;
        for (int v = target; v != -1; v = parent[v]) {
            path.push_back(v);
        }
        reverse(path.begin(), path.end());
        return path;
    }
};

