class BipartiteCheck {
private:
    int n;
    vector<vector<int>> adj;

public:
    BipartiteCheck(int n) : n(n), adj(n) {}

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // 1. Verify 2-colorability across all components in O(V + E):
    bool checkBipartite(vector<int>& side) {
        side.assign(n, -1);
        bool is_bipartite = true;
        queue<int> q;

        for (int st = 0; st < n; st++) {
            if (side[st] == -1) {
                side[st] = 0;
                q.push(st);

                while (!q.empty()) {
                    int v = q.front();
                    q.pop();

                    for (int u : adj[v]) {
                        // 2. Unvisited neighbor: assign opposite color
                        if (side[u] == -1) {
                            side[u] = side[v] ^ 1;
                            q.push(u);
                        } 
                        // 3. Conflict check: adjacent nodes share same color
                        else if (side[u] == side[v]) {
                            return false;
                        }
                    }
                }
            }
        }

        return true;
    }
};

