using namespace std;

class TreeLCA {
private:
    int n, l, timer;
    vector<vector<int>> adj;
    vector<int> tin, tout;
    vector<vector<int>> up;

    // 1. Preprocessing DFS for entry/exit times and 2^k ancestors:
    void dfs(int v, int p) {
        tin[v] = ++timer;
        up[v][0] = p;
        for (int i = 1; i <= l; i++) {
            up[v][i] = up[up[v][i - 1]][i - 1];
        }

        for (int to : adj[v]) {
            if (to != p) {
                dfs(to, v);
            }
        }

        tout[v] = ++timer;
    }

public:
    TreeLCA(int n) : n(n), timer(0), adj(n) {
        l = ceil(log2(n == 0 ? 1 : n)) + 1;
        tin.resize(n);
        tout.resize(n);
        up.assign(n, vector<int>(l + 1));
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    void build(int root = 0) {
        dfs(root, root);
    }

    // 2. O(1) Ancestor Check:
    bool is_ancestor(int u, int v) {
        return tin[u] <= tin[v] && tout[u] >= tout[v];
    }

    // 3. LCA Query in O(log N):
    int getLCA(int u, int v) {
        if (is_ancestor(u, v)) return u;
        if (is_ancestor(v, u)) return v;

        for (int i = l; i >= 0; i--) {
            if (!is_ancestor(up[u][i], v)) {
                u = up[u][i];
            }
        }

        return up[u][0];
    }
};

