using namespace std;

class TarjanBridgesAndCutpoints {
private:
    int n, timer;
    vector<vector<int>> adj;
    vector<int> tin, low;
    vector<bool> visited;

    void dfs(int v, int p, vector<pair<int, int>>& bridges, vector<bool>& is_cutpoint) {
        visited[v] = true;
        tin[v] = low[v] = ++timer;
        int children = 0;

        for (int to : adj[v]) {
            if (to == p) continue; // Skip edge leading directly back to parent

            if (visited[to]) {
                // Back-edge to an ancestor:
                low[v] = min(low[v], tin[to]);
            } else {
                // Forward tree-edge:
                dfs(to, v, bridges, is_cutpoint);
                low[v] = min(low[v], low[to]);

                // 1. Bridge condition:
                if (low[to] > tin[v]) {
                    bridges.push_back({v, to});
                }

                // 2. Non-root Articulation Point condition:
                if (low[to] >= tin[v] && p != -1) {
                    is_cutpoint[v] = true;
                }
                children++;
            }
        }

        // 3. Root Articulation Point condition:
        if (p == -1 && children > 1) {
            is_cutpoint[v] = true;
        }
    }

public:
    TarjanBridgesAndCutpoints(int n) : n(n), timer(0), adj(n) {}

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    void solve(vector<pair<int, int>>& bridges, vector<int>& cutpoints) {
        tin.assign(n, -1);
        low.assign(n, -1);
        visited.assign(n, false);
        vector<bool> is_cutpoint(n, false);
        bridges.clear();
        cutpoints.clear();

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(i, -1, bridges, is_cutpoint);
            }
        }

        for (int i = 0; i < n; i++) {
            if (is_cutpoint[i]) {
                cutpoints.push_back(i);
            }
        }
    }
};

#include <bits/stdc++.h>
using namespace std;

class KruskalMST {
public:
    struct Edge {
        int u, v, weight;
        bool operator<(const Edge& other) const {
            return weight < other.weight;
        }
    };

private:
    int n;
    vector<Edge> edges;
    vector<int> parent, rank;

    int find_set(int v) {
        if (v == parent[v]) return v;
        return parent[v] = find_set(parent[v]);
    }

    bool union_sets(int a, int b) {
        a = find_set(a);
        b = find_set(b);
        if (a == b) return false;

        if (rank[a] < rank[b]) swap(a, b);
        parent[b] = a;
        if (rank[a] == rank[b]) rank[a]++;
        return true;
    }

public:
    KruskalMST(int n) : n(n), parent(n), rank(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    void addEdge(int u, int v, int weight) {
        edges.push_back({u, v, weight});
    }

    // 1. Solve MST in O(E log E):
    pair<long long, vector<Edge>> solve() {
        // 2. Sort all edges ascending:
        sort(edges.begin(), edges.end());

        long long total_weight = 0;
        vector<Edge> mst_edges;

        // 3. Greedy selection with DSU cycle prevention:
        for (Edge& e : edges) {
            if (union_sets(e.u, e.v)) {
                total_weight += e.weight;
                mst_edges.push_back(e);
                if ((int)mst_edges.size() == n - 1) {
                    break;
                }
            }
        }

        return {total_weight, mst_edges};
    }
};

#include <bits/stdc++.h>
using namespace std;

class BellmanFord {
public:
    struct Edge {
        int a, b, cost;
    };

private:
    int n;
    const long long INF = 1e18;
    vector<Edge> edges;

public:
    BellmanFord(int n) : n(n) {}

    void addEdge(int u, int v, int cost) {
        edges.push_back({u, v, cost});
    }

    // 1. Single-Source Shortest Paths in O(V * E):
    bool solve(int src, vector<long long>& dist) {
        dist.assign(n, INF);
        dist[src] = 0;

        // Relax all edges V - 1 times:
        for (int i = 0; i < n - 1; i++) {
            bool any = false;
            for (Edge& e : edges) {
                if (dist[e.a] < INF && dist[e.a] + e.cost < dist[e.b]) {
                    dist[e.b] = dist[e.a] + e.cost;
                    any = true;
                }
            }
            if (!any) break; // Early termination optimization
        }

        // Check for negative cycle reachable from src:
        for (Edge& e : edges) {
            if (dist[e.a] < INF && dist[e.a] + e.cost < dist[e.b]) {
                return false; // Negative cycle exists!
            }
        }
        return true;
    }

    // 2. Finding and extracting any negative cycle in the graph:
    bool findNegativeCycle(vector<int>& cycle) {
        vector<long long> dist(n, 0); // Initialize to 0 to find any cycle
        vector<int> parent(n, -1);
        int x = -1;

        for (int i = 0; i < n; i++) {
            x = -1;
            for (Edge& e : edges) {
                if (dist[e.a] + e.cost < dist[e.b]) {
                    dist[e.b] = dist[e.a] + e.cost;
                    parent[e.b] = e.a;
                    x = e.b;
                }
            }
        }

        if (x == -1) {
            return false; // No negative cycle found
        }

        // Step back V times to ensure we enter the cycle:
        for (int i = 0; i < n; i++) {
            x = parent[x];
        }

        // Trace and collect the cycle:
        cycle.clear();
        for (int v = x;; v = parent[v]) {
            cycle.push_back(v);
            if (v == x && cycle.size() > 1) break;
        }
        reverse(cycle.begin(), cycle.end());
        return true;
    }
};

#include <bits/stdc++.h>
using namespace std;

class FloydWarshall {
private:
    int n;
    const long long INF = 1e18;
    vector<vector<long long>> dist;
    vector<vector<int>> parent;

public:
    FloydWarshall(int n) : n(n) {
        dist.assign(n, vector<long long>(n, INF));
        parent.assign(n, vector<int>(n, -1));

        for (int i = 0; i < n; i++) {
            dist[i][i] = 0;
            parent[i][i] = i;
        }
    }

    void addEdge(int u, int v, long long weight, bool directed = true) {
        dist[u][v] = min(dist[u][v], weight);
        parent[u][v] = v;
        if (!directed) {
            dist[v][u] = min(dist[v][u], weight);
            parent[v][u] = u;
        }
    }

    // 1. All-Pairs Shortest Paths in O(V^3):
    bool run() {
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (dist[i][k] < INF && dist[k][j] < INF) {
                        if (dist[i][k] + dist[k][j] < dist[i][j]) {
                            dist[i][j] = dist[i][k] + dist[k][j];
                            parent[i][j] = parent[i][k];
                        }
                    }
                }
            }
        }

        // 2. Negative cycle check:
        for (int i = 0; i < n; i++) {
            if (dist[i][i] < 0) {
                return false; // Negative cycle detected!
            }
        }
        return true;
    }

    // Query shortest distance between any pair:
    long long getDistance(int u, int v) {
        return dist[u][v];
    }

    // 3. Reconstruct shortest path between u and v:
    vector<int> getPath(int u, int v) {
        if (dist[u][v] >= INF) return {};
        vector<int> path = {u};
        while (u != v) {
            u = parent[u][v];
            path.push_back(u);
        }
        return path;
    }
};

#include <bits/stdc++.h>
