        weights.push_back(weight);
        values.push_back(value);
    }

    // 1. Forward 1D DP Solution in O(N * W) time and O(W) space:
    int solve() {
        vector<int> dp(W + 1, 0);

        for (int i = 0; i < n; i++) {
            // Forward iteration enables multiple inclusions of the same item:
            for (int j = weights[i]; j <= W; j++) {
                dp[j] = max(dp[j], dp[j - weights[i]] + values[i]);
            }
        }

        return dp[W];
    }
};

