class LongestIncreasingSubsequence {
public:
    LongestIncreasingSubsequence() {}

    // Computes LIS length and reconstructs the actual subsequence in O(N log N):
    pair<int, vector<int>> solve(const vector<int>& a) {
        int n = a.size();
        if (n == 0) return {0, {}};

        vector<int> tails;          // Minimal tail values for each length
        vector<int> tails_indices;  // Original array indices of tails
        vector<int> parent(n, -1);  // Predecessor pointers for reconstruction

        for (int i = 0; i < n; i++) {
            int x = a[i];
            // Binary search for the first element >= x:
            int idx = lower_bound(tails.begin(), tails.end(), x) - tails.begin();

            if (idx == (int)tails.size()) {
                tails.push_back(x);
                tails_indices.push_back(i);
            } else {
                tails[idx] = x;
                tails_indices[idx] = i;
            }

            // Record predecessor:
            if (idx > 0) {
                parent[i] = tails_indices[idx - 1];
            }
        }

        // Reconstruct the subsequence:
        int lis_len = tails.size();
        vector<int> lis_sequence;
        int cur = tails_indices.back();
        while (cur != -1) {
            lis_sequence.push_back(a[cur]);
            cur = parent[cur];
        }
        reverse(lis_sequence.begin(), lis_sequence.end());

        return {lis_len, lis_sequence};
    }
};

