class LargestZeroSubmatrix {
private:
    int n, m;

    // Helper: Largest Rectangle in Histogram in O(M) using Monotonic Stack
    int maxHistogramArea(const vector<int>& h) {
        stack<int> st;
        int max_area = 0;
        int m_len = h.size();

        for (int j = 0; j <= m_len; j++) {
            int cur_h = (j == m_len) ? 0 : h[j];

            while (!st.empty() && cur_h < h[st.top()]) {
                int height = h[st.top()];
                st.pop();
                int width = st.empty() ? j : (j - st.top() - 1);
                max_area = max(max_area, height * width);
            }
            st.push(j);
        }

        return max_area;
    }

public:
    LargestZeroSubmatrix(int rows, int cols) : n(rows), m(cols) {}

    // Finds the maximum area of a submatrix containing only 0s in O(N * M):
    int solve(const vector<vector<int>>& grid) {
        if (n == 0 || m == 0) return 0;

        vector<int> heights(m, 0);
        int max_submatrix = 0;

        // Process row by row:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 0) {
                    heights[j]++;
                } else {
                    heights[j] = 0;
                }
            }

            max_submatrix = max(max_submatrix, maxHistogramArea(heights));
        }

        return max_submatrix;
    }
};

