using namespace std;

class DivideAndConquerDP {
private:
    int n, m;
    const long long INF = 1e18;
    vector<long long> dp_prev;
    vector<long long> dp_cur;

    // Cost function C(k, j) - must satisfy Quadrangle Inequality:
    long long cost(int k, int j, const vector<long long>& pref) {
        long long sum = pref[j] - pref[k - 1];
        return sum * sum; // Example: sum of squared partition sums
    }

    // Recursive Divide & Conquer computation for a single partition stage:
    void compute(int l, int r, int opt_l, int opt_r, const vector<long long>& pref) {
        if (l > r) return;

        int mid = (l + r) / 2;
        pair<long long, int> best = {INF, -1};

        // Search for optimal splitting point k within [opt_l, min(mid, opt_r)]:
        for (int k = opt_l; k <= min(mid, opt_r); k++) {
            long long current_cost = (k == 1 ? 0 : dp_prev[k - 1]) + cost(k, mid, pref);
            if (current_cost < best.first) {
                best = {current_cost, k};
            }
        }

        dp_cur[mid] = best.first;
        int opt_mid = best.second;

        // Recursively conquer left and right halves:
        compute(l, mid - 1, opt_l, opt_mid, pref);
        compute(mid + 1, r, opt_mid, opt_r, pref);
    }

public:
    DivideAndConquerDP(int n, int m) : n(n), m(m) {
        dp_prev.assign(n + 1, INF);
        dp_cur.assign(n + 1, INF);
    }

    // Solves M-partitioning in O(M * N log N):
    long long solve(const vector<long long>& arr) {
        vector<long long> pref(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            pref[i] = pref[i - 1] + arr[i - 1];
        }

        // Base case: 1 partition
        for (int j = 1; j <= n; j++) {
            dp_prev[j] = cost(1, j, pref);
        }

        // Compute for partitions 2 to m:
        for (int i = 2; i <= m; i++) {
            compute(1, n, 1, n, pref);
            dp_prev = dp_cur;
        }

        return dp_prev[n];
    }
};

