class KMP {
public:
    KMP() {}

    // 1. Compute Prefix Function (pi-array) in O(N):
    vector<int> computePrefix(const string& s) {
        int n = s.length();
        vector<int> pi(n, 0);

        for (int i = 1; i < n; i++) {
            int j = pi[i - 1];

            // 2. Roll back to smaller prefix-suffix boundaries on mismatch:
            while (j > 0 && s[i] != s[j]) {
                j = pi[j - 1];
            }

            // 3. Extend boundary if characters match:
            if (s[i] == s[j]) {
                j++;
            }

            pi[i] = j;
        }

        return pi;
    }

    // 4. Linear Pattern Matching in O(N + M):
    vector<int> search(const string& text, const string& pattern) {
        int n = pattern.length();
        int m = text.length();
        vector<int> occurrences;
        if (n == 0 || m < n) return occurrences;

        // Composite string with sentinel delimiter:
        string s = pattern + "#" + text;
        vector<int> pi = computePrefix(s);

        // Scan the text segment of the composite string:
        for (int i = n + 1; i < (int)s.length(); i++) {
            if (pi[i] == n) {
                // Match found! Calculate 0-based start index in text:
                occurrences.push_back(i - 2 * n);
            }
        }

        return occurrences;
    }
};

