class Manacher {
private:
    string original;
    string transformed;
    vector<int> p; // Radii array

public:
    Manacher(const string& s) : original(s) {
        // Interleave original string with sentinels: e.g. "aba" -> "^#a#b#a#$"
        transformed = "^";
        for (char c : s) {
            transformed += "#";
            transformed += c;
        }
        transformed += "#$";

        int n = transformed.length();
        p.assign(n, 0);
        int c = 0, r = 0; // Active palindrome center and right boundary

        // 1. Manacher's Linear Expansion in O(N):
        for (int i = 1; i < n - 1; i++) {
            int i_mirror = 2 * c - i;

            // 2. Initialize from mirror if inside boundary:
            if (i < r) {
                p[i] = min(r - i, p[i_mirror]);
            }

            // 3. Trivial expansion beyond right boundary r:
            while (transformed[i + p[i] + 1] == transformed[i - p[i] - 1]) {
                p[i]++;
            }

            // 4. Update rightmost center and boundary:
            if (i + p[i] > r) {
                c = i;
                r = i + p[i];
            }
        }
    }

    // 5. Query Longest Palindromic Substring:
    string getLongestPalindrome() {
        int max_len = 0;
        int center_idx = 0;

        for (int i = 1; i < (int)transformed.length() - 1; i++) {
            if (p[i] > max_len) {
                max_len = p[i];
                center_idx = i;
            }
        }

        int start = (center_idx - max_len) / 2;
        return original.substr(start, max_len);
    }

    // 6. O(1) Palindrome Query for arbitrary substring [l, r]:
    bool isPalindrome(int l, int r) {
        int t_center = (l + 1) + (r + 1);
        int expected_radius = r - l + 1;
        return p[t_center] >= expected_radius;
    }
};

#include <bits/stdc++.h>
using namespace std;

class AhoCorasick {
private:
    static const int ALPHABET_SIZE = 26;

    struct Vertex {
        int next[ALPHABET_SIZE];
        int go[ALPHABET_SIZE];
        int link;
        int exit_link;
        vector<int> pattern_indices; // Indices of patterns ending at this vertex

        Vertex() {
            fill(begin(next), end(next), -1);
            fill(begin(go), end(go), -1);
            link = -1;
            exit_link = -1;
        }
    };

    vector<Vertex> t;
    vector<string> patterns;

public:
    AhoCorasick() {
        t.emplace_back(); // Initialize root at index 0
    }

    // 1. Insert Pattern into Trie:
    void insert(const string& s, int pattern_id) {
        int v = 0;
        for (char ch : s) {
            int c = ch - 'a';
            if (t[v].next[c] == -1) {
                t[v].next[c] = t.size();
                t.emplace_back();
            }
            v = t[v].next[c];
        }
        t[v].pattern_indices.push_back(pattern_id);
    }

    // 2. Build Suffix Links and Transition Matrix via BFS in O(sum|P| * Sigma):
    void build() {
        queue<int> q;
        t[0].link = 0;

        for (int c = 0; c < ALPHABET_SIZE; c++) {
            if (t[0].next[c] != -1) {
                int child = t[0].next[c];
                t[child].link = 0;
                t[0].go[c] = child;
                q.push(child);
            } else {
                t[0].go[c] = 0;
            }
        }

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            // Setup exit link (shortcut to matched patterns):
            if (t[t[v].link].pattern_indices.empty()) {
                t[v].exit_link = t[t[v].link].exit_link;
            } else {
                t[v].exit_link = t[v].link;
            }

            for (int c = 0; c < ALPHABET_SIZE; c++) {
                if (t[v].next[c] != -1) {
                    int child = t[v].next[c];
                    t[child].link = t[t[v].link].go[c];
                    t[v].go[c] = child;
                    q.push(child);
                } else {
                    t[v].go[c] = t[t[v].link].go[c];
                }
            }
        }
    }

    // 3. Multi-Pattern Search in O(N + Total Matches):
    vector<vector<int>> search(const string& text) {
        vector<vector<int>> matches; // {pattern_id, end_position}
        int v = 0;

        for (int i = 0; i < (int)text.length(); i++) {
            v = t[v].go[text[i] - 'a'];

            // Collect all matching patterns at current position:
            for (int u = v; u > 0; u = t[u].exit_link) {
                for (int id : t[u].pattern_indices) {
                    matches.push_back({id, i});
                }
            }
        }

        return matches;
    }
};

#include <bits/stdc++.h>
using namespace std;

class BinaryExponentiation {
public:
    BinaryExponentiation() {}

    // 1. Fast Modular Exponentiation (a^b mod m) in O(log b):
    static long long power(long long a, long long b, long long m) {
        a %= m;
        long long res = 1;

        while (b > 0) {
            // If the current lowest bit is 1, multiply into result:
            if (b & 1) {
                res = (__int128)res * a % m;
            }
            // Square the base for the next bit position:
            a = (__int128)a * a % m;
            // Shift exponent right:
            b >>= 1;
        }

        return res;
    }

    // 2. Standard Non-Modular Power (a^b) in O(log b):
    static long long power(long long a, long long b) {
        long long res = 1;
        while (b > 0) {
            if (b & 1) res *= a;
            a *= a;
            b >>= 1;
        }
        return res;
    }

    // 3. Modular Multiplicative Inverse (Fermat's Little Theorem for prime m):
    static long long modInverse(long long a, long long m) {
        // a^(m-2) mod m
        return power(a, m - 2, m);
    }
};

#include <bits/stdc++.h>
using namespace std;

class EuclideanAlgorithm {
public:
    EuclideanAlgorithm() {}

    // 1. Classical Euclidean GCD in O(log min(a, b)):
    static long long gcd(long long a, long long b) {
        while (b) {
            a %= b;
            swap(a, b);
        }
        return a;
    }

    // 2. Least Common Multiple (LCM):
    static long long lcm(long long a, long long b) {
        return (a / gcd(a, b)) * b;
    }

    // 3. Extended Euclidean Algorithm (finds x, y such that a*x + b*y = gcd(a, b)):
    static long long extendedGcd(long long a, long long b, long long& x, long long& y) {
        if (b == 0) {
            x = 1;
            y = 0;
            return a;
        }
        long long x1, y1;
        long long g = extendedGcd(b, a % b, x1, y1);
        x = y1;
        y = x1 - y1 * (a / b);
        return g;
    }

    // 4. Solve Linear Diophantine Equation (a*x + b*y = c):
    static bool solveDiophantine(long long a, long long b, long long c, long long& x0, long long& y0, long long& g) {
        g = extendedGcd(abs(a), abs(b), x0, y0);
        if (c % g != 0) {
            return false; // No integer solution exists!
        }

        x0 *= c / g;
        y0 *= c / g;
        if (a < 0) x0 = -x0;
        if (b < 0) y0 = -y0;
        return true;
    }
};

#include <bits/stdc++.h>
using namespace std;

class LinearSieve {
private:
    int n;
    vector<int> spf;   // Smallest Prime Factor for each number
    vector<int> primes; // Ordered list of all primes up to n

public:
    // 1. Strict O(N) Linear Precomputation:
    LinearSieve(int n) : n(n), spf(n + 1, 0) {
        for (int i = 2; i <= n; i++) {
            if (spf[i] == 0) {
                spf[i] = i;
                primes.push_back(i);
            }

            for (int p : primes) {
                // Break if prime exceeds smallest prime factor of i, or exceeds n:
                if (p > spf[i] || i * p > n) {
                    break;
                }
                spf[i * p] = p; // Marked strictly once by its smallest prime factor
            }
        }
    }

    // 2. O(1) Primality Check:
    bool isPrime(int x) const {
        return x >= 2 && spf[x] == x;
    }

    // 3. Retrieve All Primes up to N:
    const vector<int>& getPrimes() const {
        return primes;
    }

    // 4. Retrieve Smallest Prime Factor (SPF) in O(1):
    int getSPF(int x) const {
        return spf[x];
    }

    // 5. Query Prime Factorization of X in strictly O(log X):
    vector<pair<int, int>> factorize(int x) const {
        vector<pair<int, int>> factors; // {prime, exponent}
        while (x > 1) {
            int p = spf[x];
            int count = 0;
            while (x % p == 0) {
                count++;
                x /= p;
            }
            factors.push_back({p, count});
        }
        return factors;
    }
};

#include <bits/stdc++.h>
using namespace std;

class SubmaskEnumeration {
public:
    SubmaskEnumeration() {}

    // 1. Iterate through all submasks of a specific mask in O(2^k):
    static vector<int> getSubmasks(int mask) {
        vector<int> submasks;
        // s = (s - 1) & mask generates submasks in strictly decreasing order:
        for (int s = mask; s > 0; s = (s - 1) & mask) {
            submasks.push_back(s);
        }
        submasks.push_back(0); // Empty submask
        return submasks;
    }

    // 2. Count Total Submask Operations for universe size N in O(3^N):
    static long long countAllSubmaskIterations(int n) {
        long long total_steps = 0;
        int max_mask = 1 << n;

        for (int mask = 0; mask < max_mask; mask++) {
            for (int s = mask; s > 0; s = (s - 1) & mask) {
                total_steps++;
            }
            total_steps++; // For submask 0
        }

        return total_steps; // Exactly equal to 3^N
    }

    // 3. Essential Bit Manipulation Utilities:
    static int countSetBits(int mask) { return __builtin_popcount(mask); }
    static int lowestSetBit(int mask) { return mask & (-mask); }
    static int clearLowestBit(int mask) { return mask & (mask - 1); }
};

#include <bits/stdc++.h>
using namespace std;

class FloydCycleFinding {
public:
    FloydCycleFinding() {}

    // Simulates functional graph cycle detection: x_{i+1} = f(x_i)
    template <typename Func>
    static pair<int, int> findCycle(int x0, Func f) {
        // Phase 1: Detecting Cycle Presence
        int tortoise = f(x0);
        int hare = f(f(x0));

        while (tortoise != hare) {
            tortoise = f(tortoise);
            hare = f(f(hare));
        }

        // Phase 2: Finding the Cycle Entrance (mu)
        int mu = 0;
        tortoise = x0;
        while (tortoise != hare) {
            tortoise = f(tortoise);
            hare = f(hare);
            mu++;
        }

        // Phase 3: Finding the Cycle Length (lambda)
        int lambda = 1;
        hare = f(tortoise);
        while (tortoise != hare) {
            hare = f(hare);
            lambda++;
        }

        return {mu, lambda}; // {cycle_start_index, cycle_length}
    }
};

#include <bits/stdc++.h>
using namespace std;

class Quickselect {
private:
    // Partition helper using Lomuto/Hoare strategy:
    static int partition(vector<int>& a, int l, int r) {
        // Randomized pivot to guarantee average O(N):
        int random_idx = l + rand() % (r - l + 1);
        swap(a[random_idx], a[r]);

        int pivot = a[r];
        int i = l;

        for (int j = l; j < r; j++) {
            if (a[j] <= pivot) {
                swap(a[i], a[j]);
                i++;
            }
        }
        swap(a[i], a[r]);
        return i; // Final index of the pivot
    }

public:
    Quickselect() {
        srand(time(nullptr));
    }

    // 1. Recursive Quickselect in Average O(N):
    static int select(vector<int>& a, int k) {
        int l = 0, r = a.size() - 1;

        while (l <= r) {
            int pivot_idx = partition(a, l, r);

            if (pivot_idx == k) {
                return a[pivot_idx]; // Found k-th smallest element!
            } else if (k < pivot_idx) {
                r = pivot_idx - 1; // Recurse only into left partition
            } else {
                l = pivot_idx + 1; // Recurse only into right partition
            }
        }

        return -1;
    }
};

#include <bits/stdc++.h>
using namespace std;

class KadaneAlgorithm {
public:
    struct SubsegmentResult {
        long long max_sum;
        int start_idx;
        int end_idx;
    };

    KadaneAlgorithm() {}

    // 1. Kadane's Algorithm with Subsegment Range Extraction in O(N):
    static SubsegmentResult solve(const vector<int>& a) {
        int n = a.size();
        if (n == 0) return {0, -1, -1};

        long long max_so_far = a[0];
        long long cur_sum = a[0];

        int best_l = 0, best_r = 0;
        int cur_l = 0;

        for (int i = 1; i < n; i++) {
            // 2. Decide whether to extend existing subarray or start anew:
            if (cur_sum + a[i] < a[i]) {
                cur_sum = a[i];
                cur_l = i;
            } else {
                cur_sum += a[i];
            }

            // 3. Update global maximum and boundaries:
            if (cur_sum > max_so_far) {
                max_so_far = cur_sum;
                best_l = cur_l;
                best_r = i;
            }
        }

        return {max_so_far, best_l, best_r};
    }
};
